body {
  background-color: #f5f6f8;
  color: #18181b;
  font-family: system-ui, "Segoe UI", sans-serif;
  line-height: 1.6;
  padding: 16px;
}

h1 { font-size: 26px; }

#output {
  list-style: none;
  padding: 0;
  max-width: 520px;
}

#output li {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  background-color: #ffffff;
  border-radius: 8px;
  padding: 10px 14px;
  margin-bottom: 8px;
}

#output span { color: #3f3f46; font-size: 14px; }

#output code {
  font-family: ui-monospace, "Cascadia Mono", monospace;
  font-weight: 700;
  color: #1d4ed8;
}

// Shop.mn — TypeScript.
// Preview нь төрлийг хуулаад ажиллуулна; «Шалгах» дарахад ЖИНХЭНЭ TypeScript
// хөрвүүлэгч төрлүүдийг чинь шалгана.

// энд бичнэ үү
function cartTotal(items) {
  return items.reduce((sum, item) => sum + item.price * item.quantity, 0);
}

// Tier 1-д модуль байхгүй тул функцүүдээ ил гаргана.
(globalThis as unknown as Record<string, unknown>).SHOP = { cartTotal };

// Үр дүнг харуулах жижиг самбар. Энэ файлыг өөрчлөх шаардлагагүй.

const output = document.getElementById("output");

function row(label, value) {
  const line = document.createElement("li");
  const name = document.createElement("span");
  name.textContent = label;
  const result = document.createElement("code");
  result.textContent = value;
  line.append(name, result);
  output.append(line);
}

(function () {
  const shop = window.SHOP || {};
  window.OUT = {};

  const items = [
    { id: 1, name: "Монгол дээл", price: 129000, quantity: 2 },
    { id: 2, name: "Малгай", price: 45000, quantity: 1 },
  ];

  try {
    if (typeof shop.cartTotal === "function") {
      window.OUT.total = shop.cartTotal(items);
      row("cartTotal(2 бараа)", String(window.OUT.total));
    }

    if (typeof shop.applyDiscount === "function") {
      window.OUT.discounted = shop.applyDiscount(100000, "ШИНЭ10");
      window.OUT.untouched = shop.applyDiscount(100000, "БАЙХГҮЙ");
      row('applyDiscount(100000, "ШИНЭ10")', String(window.OUT.discounted));
      row('applyDiscount(100000, "БАЙХГҮЙ")', String(window.OUT.untouched));
    }

    if (typeof shop.describeStatus === "function") {
      window.OUT.statuses = ["loading", "error", "ready"].map(shop.describeStatus);
      for (const [i, s] of ["loading", "error", "ready"].entries()) {
        row('describeStatus("' + s + '")', window.OUT.statuses[i]);
      }
    }

    if (typeof shop.first === "function") {
      window.OUT.firstItem = shop.first(items);
      window.OUT.firstEmpty = shop.first([]);
      row("first(items).name", String(window.OUT.firstItem && window.OUT.firstItem.name));
      row("first([])", String(window.OUT.firstEmpty));
    }
  } catch (problem) {
    row("алдаа", problem.message);
  }

  document.body.dataset.ready = "1";
})();

